import fs from "node:fs"
import path from "node:path"
import { AGENT_HOME, log, sleep, withLock } from "./config.ts"
import {
  type AgentMemory,
  type MemorySource,
  type MemoryType,
  readIfExists,
  sha1,
  syncMemories,
  titleFrom,
} from "./memories.ts"
import type { NotionClient } from "./notion.ts"

// Codex memories (features.memories) are generated by Codex itself, in the background:
// phase 1 extracts notes from each idle session, phase 2 consolidates them into
// $CODEX_HOME/memories/memory_summary.md and MEMORY.md. This module parses those files.

// Codex memories get their key from type and title once parsed.
type CodexEntry = Omit<AgentMemory, "key">

const POLL_MS = 5000

export const codexSource: MemorySource = {
  name: "Codex",
  dir: path.join(AGENT_HOME, "memories"),
  parse: parseCodexMemories,
  emptyHint: "is [features] memories = true set in Codex?",
}

export function parseCodexMemories(dir: string): AgentMemory[] {
  const out = [
    ...parseSummary(readIfExists(path.join(dir, "memory_summary.md"))),
    ...parseMemoryFile(readIfExists(path.join(dir, "MEMORY.md"))),
  ].filter((m) => !isPlaceholder(m.content))
  return dedupe(out).map((m) => ({
    ...m,
    key: `${m.type}|${m.title}`,
    content: m.content.replace(/\s*\[Task \d+\]/g, ""),
  }))
}

// Codex has no hook for "memories updated", so a hook worker watches Codex's own job table
// and the memory files, and imports as soon as a consolidation run finishes.
export async function watchMemories(
  client: NotionClient,
  opts: { startWindowMs: number; maxMs: number }
): Promise<void> {
  const started = Date.now()
  let lastHash = memoryFilesHash()
  let sawRunning = false
  while (Date.now() - started < opts.maxMs) {
    await sleep(POLL_MS)
    const running = await memoryJobRunning()
    sawRunning ||= running
    const hash = memoryFilesHash()
    if (hash !== lastHash && !running) {
      log("memories: Codex updated its memory files, importing")
      await withLock(() => syncMemories(client, codexSource))
      lastHash = hash
    }
    if (!running && (sawRunning || Date.now() - started > opts.startWindowMs))
      return
  }
}

function parseSummary(text: string): CodexEntry[] {
  const out: CodexEntry[] = []
  for (const section of sections(text, 2)) {
    if (/^user profile/i.test(section.title) && section.body.trim())
      out.push({
        type: "Profile",
        title: "Codex user profile",
        content: section.body.trim(),
        from: "memory_summary.md › User Profile",
      })
    if (/^user preferences/i.test(section.title))
      for (const b of bullets(section.body))
        out.push({
          type: "Preference",
          title: preferenceTitle(b),
          content: b,
          from: "memory_summary.md › User preferences",
        })
  }
  return out
}

function parseMemoryFile(text: string): CodexEntry[] {
  const out: CodexEntry[] = []
  for (const group of sections(text, 1)) {
    const subsections = sections(group.body, 2)
    const scope = group.body.match(/^scope:\s*(.+)$/m)?.[1]
    const appliesTo = group.body.match(/^applies_to:\s*(.+)$/m)?.[1]
    const knowledge = subsections.filter((s) =>
      /^(reusable knowledge|failures)/i.test(s.title)
    )
    const tasks = subsections
      .filter((s) => /^task \d+/i.test(s.title))
      .map((s) => s.title.replace(/^Task \d+:\s*/i, ""))
    if (knowledge.length || tasks.length) {
      const content = [
        scope && `Scope: ${scope}`,
        appliesTo && `Applies to: ${appliesTo}`,
        tasks.length && `Tasks:\n${tasks.map((t) => `- ${t}`).join("\n")}`,
        ...knowledge.map(
          (k) =>
            `${k.title}:\n${bullets(k.body)
              .map((b) => `- ${b}`)
              .join("\n")}`
        ),
      ]
        .filter(Boolean)
        .join("\n\n")
      out.push({
        type: "Work",
        title: titleFrom(group.title.replace(/^Task Group:\s*/i, "")),
        content,
        from: `MEMORY.md › ${group.title}`,
      })
    }
    for (const s of subsections.filter((s) =>
      /^user preferences/i.test(s.title)
    ))
      for (const b of bullets(s.body))
        out.push({
          type: "Preference",
          title: preferenceTitle(b),
          content: b,
          from: `MEMORY.md › ${group.title}`,
        })
  }
  return out
}

// The same preference often appears in both files with different wording around a quote.
function dedupe(memories: CodexEntry[]): CodexEntry[] {
  const seen: { type: MemoryType; key: string }[] = []
  return memories.filter((m) => {
    const key = normalizeKey(quoteOf(m.content) ?? m.content)
    if (
      seen.some(
        (s) => s.type === m.type && (s.key.includes(key) || key.includes(s.key))
      )
    )
      return false
    seen.push({ type: m.type, key })
    return true
  })
}

async function memoryJobRunning(): Promise<boolean> {
  const db = path.join(AGENT_HOME, "memories_1.sqlite")
  if (!fs.existsSync(db)) return false
  try {
    const { DatabaseSync } = await import("node:sqlite")
    const conn = new DatabaseSync(db, { readOnly: true })
    try {
      return (
        conn
          .prepare("SELECT 1 FROM jobs WHERE status = 'running' LIMIT 1")
          .all().length > 0
      )
    } finally {
      conn.close()
    }
  } catch (e) {
    log(
      "memories: job table unavailable:",
      e instanceof Error ? e.message : String(e)
    )
    return false
  }
}

function memoryFilesHash(): string {
  return sha1(
    ["MEMORY.md", "memory_summary.md"]
      .map((f) => readIfExists(path.join(codexSource.dir, f)))
      .join("\0")
  )
}

function sections(
  text: string,
  level: number
): { title: string; body: string }[] {
  const heading = new RegExp(`^${"#".repeat(level)} (.+)$`, "gm")
  const out: { title: string; body: string }[] = []
  let prev: { title: string; end: number } | undefined
  for (const match of text.matchAll(heading)) {
    const index = match.index ?? 0
    if (prev) out.push({ title: prev.title, body: text.slice(prev.end, index) })
    prev = { title: match[1].trim(), end: index + match[0].length }
  }
  if (prev) out.push({ title: prev.title, body: text.slice(prev.end) })
  return out
}

function bullets(section: string): string[] {
  return section
    .split("\n")
    .filter((l) => /^\s*- /.test(l))
    .map((l) => l.replace(/^\s*- /, "").trim())
    .filter(Boolean)
}

// Codex seeds memory files with placeholder text such as "No preferences recorded yet."
function isPlaceholder(content: string): boolean {
  const text = content.trim()
  return text.length < 12 || /^(no|not)\b[^.]*\b(yet|recorded)\b/i.test(text)
}

function quoteOf(text: string): string | undefined {
  return text.match(/[“"]([^”"]{8,})[”"]/)?.[1]
}

// Prefer the user's own words when Codex quoted them; otherwise use the text before "->".
function preferenceTitle(bullet: string): string {
  const quote = quoteOf(bullet)
  return titleFrom(
    quote && quote.length >= 25 ? quote : bullet.split(/\s->\s/)[0]
  )
}

function normalizeKey(text: string): string {
  return text
    .toLowerCase()
    .replace(/\[task \d+\]/g, "")
    .replace(/[^a-z0-9]/g, "")
}
